    /** @param  array<string, mixed>  $context  Runtime account context. */
    public function createTool(string $class, array $context = []): Tool { return new $class($this->resolveService($context)); }

    /** @param  array<string, mixed>  $context  Runtime account context. */
    private function resolveService(array $context = []): MicrosoftGraphSecurityService
    {
        $account = $context['account'] ?? null;
        if ($account !== null) {
            $creds = app(CredentialResolver::class);
            return new MicrosoftGraphSecurityService(accessToken: $creds->get('microsoft-graph-security', 'access_token', '', $account), baseUrl: $creds->get('microsoft-graph-security', 'base_url', 'https://graph.microsoft.com/v1.0', $account));
        }

        return app(MicrosoftGraphSecurityService::class);
    }

    public function luaDocsPath(): ?string { return __DIR__ . '/../lua-docs/microsoft-graph-security.md'; }
    public function isIntegration(): bool { return true; }
